SOURCE_CLAIM_JSON: {"title":"STATISTICAL COMMUNIQUÉ OF THE PEOPLE'S REPUBLIC OF CHINA ON THE 2023 NATIONAL ECONOMIC AND SOCIAL DEVELOPMENT","publisher":"National Bureau of Statistics of China","publication_date":"2024-02-29","url":"https://www.stats.gov.cn/english/PressRelease/202402/t20240228_1947918.html?os=ios","claim":"Official 2023 Chinese statistics reported 5.2 percent annual GDP growth, 5.4 percent per-capita GDP growth, 0.2 percent CPI inflation, 12.44 million new urban jobs, a 5.2 percent average urban surveyed unemployment rate, and a large urban-rural income gap, with urban per-capita disposable income at 51,821 yuan and rural per-capita disposable income at 21,691 yuan.","locator":"The communiqué text in the search result excerpt, including the GDP, employment, inflation, and income paragraphs.","provisional_id":"WEB-5B-005","canonical_fact_key":"nbs_2023_growth_jobs_inflation_income","disposition":"final_evidence","chapter_ids":["5B"],"methodology_ids":[],"source_type":"official_statistics","source_confidence":"medium","source_confidence_reason":"Primary official statistical communiqué, but the source is state-controlled and some indicators are later revised or context-dependent.","final_evidence_use":"final_evidence","period_fit":"target_period_current","ruler_attribution":"moderate_indirect","contrary_evidence":"Independent sources describe the recovery as fragile and note substantial weaknesses in property, debt, and confidence.","underlying_fact_key":"china_2023_official_macro_and_household_stats","lenses":["5B.8","5B.9","5B.10"]}

SOURCE_CLAIM_JSON: {"title":"Households' Income and Consumption Expenditure in 2023","publisher":"National Bureau of Statistics of China","publication_date":"2024-01-18","url":"https://www.stats.gov.cn/english/PressRelease/202402/t20240201_1947120.html?form=MG0AV3","claim":"China's official household survey for 2023 reported nationwide per-capita disposable income of 39,218 yuan, with urban residents at 51,821 yuan and rural residents at 21,691 yuan, showing a large urban-rural income gap even as both groups posted nominal and real growth.","locator":"Opening section under 'I. Households' Income' in the communiqué text.","provisional_id":"WEB-5B-006","canonical_fact_key":"nbs_household_income_urban_rural_gap_2023","disposition":"final_evidence","chapter_ids":["5B"],"methodology_ids":[],"source_type":"official_statistics","source_confidence":"medium","source_confidence_reason":"Primary official household-income data, useful for distributional analysis but still subject to state statistical limits.","final_evidence_use":"final_evidence","period_fit":"target_period_current","ruler_attribution":"moderate_indirect","contrary_evidence":"The official figures show growth in both urban and rural incomes, but they do not resolve questions about job quality, precarity, or regional inequality.","underlying_fact_key":"china_2023_household_income_distribution","lenses":["5B.8","5B.10"]}

SOURCE_CLAIM_JSON: {"title":"国务院关于2023年度中央预算执行和其他财政收支的审计工作报告","publisher":"National Audit Office of China / NPC record","publication_date":"2024-06-25","url":"https://www.npc.gov.cn/npc/c2/c30834/202406/t20240627_437805.html","claim":"The 2023 central-budget audit reported that 6,800 billion yuan of central fiscal investment was managed for major infrastructure and strategic areas, but it also found problems including incomplete and imprecise reporting of capital expenditure, new hidden local debt, and new arrears created by some regions after debt cleanup efforts began.","locator":"The budget, infrastructure, and local-debt sections in the body text, especially the paragraph beginning '国家发展改革委管理分配中央财政投资6800亿元' and the later '地方债务管理不够严格' section.","provisional_id":"WEB-5B-007","canonical_fact_key":"audit_2023_budget_investment_and_hidden_debt","disposition":"final_evidence","chapter_ids":["5B"],"methodology_ids":[],"source_type":"official_audit","source_confidence":"high","source_confidence_reason":"Primary audit of 2023 fiscal execution with concrete amounts and identified irregularities.","final_evidence_use":"final_evidence","period_fit":"target_period_current","ruler_attribution":"strong_indirect","contrary_evidence":"The same report says most regions and departments continued macro-control and kept recovery going, so the audit is not a one-sided failure finding.","underlying_fact_key":"china_2023_fiscal_execution_hidden_debt_and_public_investment","lenses":["5B.3","5B.5","5B.6","5B.9"]}

