SOURCE_CLAIM_JSON: {"title":"2023年中国正风反腐“成绩单”","publisher":"CCDI / Xinhua","publication_date":"2023-12-26","url":"https://www.ccdi.gov.cn/yaowenn/202312/t20231226_317271.html","claim":"China's anti-corruption system reported a continued high-pressure campaign in 2023, with 470,000 cases handled in the first three quarters, 54 centrally managed cadres placed under investigation in the first three quarters, and 79,721 violations of the eight-point rules handled in January through October, which shows both the scale of enforcement and the regime's reliance on internal discipline rather than external accountability.","locator":"The body text summarizing first-three-quarter and January-October enforcement figures.","provisional_id":"WEB-5B-009","canonical_fact_key":"ccdi_2023_high_pressure_anticorruption","disposition":"final_evidence","chapter_ids":["5B"],"methodology_ids":[],"source_type":"official_anticorruption_report","source_confidence":"medium","source_confidence_reason":"Primary party-discipline source with hard numbers, but it is self-reporting and does not itself prove effectiveness or fairness.","final_evidence_use":"final_evidence","period_fit":"target_period_current","ruler_attribution":"strong_indirect","contrary_evidence":"High enforcement counts may indicate persistent corruption, bureaucratic fear, or selective discipline rather than clean governance.","underlying_fact_key":"china_2023_anticorruption_enforcement_scale","lenses":["5B.5","5B.7"]}

